def set_run_format(paragraph, size: float = 12) -> None:
    for run in paragraph.runs:
        run.font.name = "Times New Roman"
        run.font.size = Pt(size)


def main() -> None:
    document = Document(SOURCE)
    for index, value in PARAGRAPHS.items():
        paragraph = document.paragraphs[index]
        paragraph.clear()
        paragraph.add_run(value)
        set_run_format(paragraph)
        if paragraph.style.name == "Normal":
            paragraph.alignment = (
                WD_ALIGN_PARAGRAPH.LEFT if index >= 55 else WD_ALIGN_PARAGRAPH.JUSTIFY
            )
            paragraph.paragraph_format.line_spacing = 1.5

    for table, rows in zip(document.tables, TABLES, strict=True):
        for row_index, (row, values) in enumerate(zip(table.rows, rows, strict=True)):
            for cell, value in zip(row.cells, values, strict=True):
                cell.text = value
                for paragraph in cell.paragraphs:
                    paragraph.alignment = WD_ALIGN_PARAGRAPH.LEFT
                    paragraph.paragraph_format.line_spacing = 1.15
                    paragraph.paragraph_format.space_after = Pt(0)
                    set_run_format(paragraph, 10.5)
                    if row_index == 0:
                        for run in paragraph.runs:
                            run.bold = True

    document.core_properties.title = "Разработка и интеграция программного обеспечения — задание 3"
    document.core_properties.subject = "Русская версия отчета по проекту novelty similarity detection model"
    document.save(OUTPUT)
    print(OUTPUT)


if __name__ == "__main__":
    main()
